<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Dezerx; use Illuminate\Http\JsonResponse; use Illuminate\Database\Eloquent\Builder; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\ClientApiRequest; use Pterodactyl\Models\Dezerx\StaffProfile; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\Server; use Pterodactyl\Models\User; use Pterodactyl\Services\Dezerx\Staff\Staff; use Pterodactyl\Services\Dezerx\Staff\StaffChat; use Pterodactyl\Services\Dezerx\Staff\StaffPresenter; use Pterodactyl\Services\Dezerx\Staff\StaffPresets; use Pterodactyl\Services\Dezerx\Staff\StaffRecord; use Pterodactyl\Services\Dezerx\Staff\StaffRequests; use Pterodactyl\Services\Dezerx\Staff\StaffReviews; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class StaffController extends ClientApiController { private const LIMIT = 30; public function __construct(private StaffRequests $requests) { parent::__construct(); } public function index(ClientApiRequest $request): JsonResponse { $user = $this->actor($request); $payload = [ 'record' => StaffRecord::forUser($user), 'queue' => StaffPresenter::collection($this->requests->queueFor($user)->limit(self::LIMIT)->get(), $user), 'mine' => StaffPresenter::collection($this->requests->mineFor($user)->limit(self::LIMIT)->get(), $user, true), 'history' => StaffPresenter::collection($this->requests->historyFor($user)->limit(self::LIMIT)->get(), $user), 'presets' => StaffPresets::describe(), 'admin' => $user->root_admin === true, 'canAsk' => Staff::flag('allow_staff_requests'), ]; if ($user->root_admin === true) { $everything = StaffRequest::query() ->with(['server.egg', 'server.user', 'staff', 'target', 'requester', 'feedback']) ->latest('id') ->limit(self::LIMIT); if ($request->query('done') !== '1') { $everything->open(); } $payload['all'] = StaffPresenter::collection($everything->get(), $user); } return new JsonResponse($payload); } public function leaderboard(ClientApiRequest $request): JsonResponse { $this->actor($request); $month = trim((string) $request->query('month', '')); return new JsonResponse(StaffReviews::board($month === '' ? null : $month)); } public function badges(ClientApiRequest $request): JsonResponse { return new JsonResponse(StaffRecord::badges($request->user())); } public function claim(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $updated = $this->requests->claim($this->visible($user, $uuid), $user); return $this->single($updated, $user); } public function withdraw(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $updated = $this->requests->withdraw($this->visible($user, $uuid), $user); return $this->single($updated, $user); } public function resign(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $data = $request->validate(['note' => ['sometimes', 'nullable', 'string', 'max:1000']]); $updated = $this->requests->resign( $this->visible($user, $uuid), $user, (string) ($data['note'] ?? '') ); return $this->single($updated, $user); } public function decline(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $data = $request->validate(['reason' => ['required', 'string', 'min:1', 'max:1000']]); $updated = $this->requests->decline($this->visible($user, $uuid), $user, (string) $data['reason']); return $this->single($updated, $user); } public function resolve(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $data = $request->validate(['note' => ['sometimes', 'nullable', 'string', 'max:1000']]); $updated = $this->requests->resolve( $this->visible($user, $uuid), $user, (string) ($data['note'] ?? '') ); return $this->single($updated, $user); } public function askExtension(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $data = $request->validate([ 'minutes' => ['required', 'integer', 'between:1,43200'], 'note' => ['sometimes', 'nullable', 'string', 'max:1000'], ]); $updated = $this->requests->askExtension( $this->visible($user, $uuid), $user, (int) $data['minutes'], (string) ($data['note'] ?? '') ); return $this->single($updated, $user); } public function revoke(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); if ($user->root_admin !== true) { throw new NotFoundHttpException(); } $data = $request->validate(['reason' => ['sometimes', 'nullable', 'string', 'max:1000']]); $found = StaffRequest::query()->where('uuid', $uuid)->first(); if ($found === null) { throw new NotFoundHttpException(); } $updated = $this->requests->revoke($found, $user, (string) ($data['reason'] ?? '')); return $this->single($updated, $user); } public function ask(ClientApiRequest $request): JsonResponse { $user = $this->actor($request); $data = $request->validate([ 'server' => ['required', 'string', 'max:16'], 'reason' => ['required', 'string', 'min:1', 'max:2000'], 'scope' => ['required', 'string', 'in:' . implode(',', StaffPresets::SCOPES)], 'open_ended' => ['sometimes', 'boolean'], 'duration_minutes' => ['sometimes', 'nullable', 'integer', 'between:1,43200'], ]); $server = Server::query()->where('uuidShort', $data['server'])->first(); if ($server === null) { throw new NotFoundHttpException(); } $created = $this->requests->open($server, $user, [ 'direction' => StaffRequest::DIRECTION_STAFF, 'reason' => (string) $data['reason'], 'scope' => (string) $data['scope'], 'open_ended' => (bool) ($data['open_ended'] ?? false), 'duration_minutes' => $data['duration_minutes'] ?? null, ]); return $this->single($created, $user); } public function availability(ClientApiRequest $request): JsonResponse { $user = $this->actor($request); $data = $request->validate(['value' => ['required', 'boolean']]); $value = (bool) $data['value']; $profile = $user->staffProfile; if ($profile instanceof StaffProfile) { $profile->forceFill(['available' => $value])->saveOrFail(); } else { StaffProfile::query()->create(['user_id' => $user->id, 'available' => $value]); } return new JsonResponse(['available' => $value]); } public function messages(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $found = $this->visible($user, $uuid); if (!StaffChat::canRead($found, $user)) { throw new NotFoundHttpException(); } $after = (int) $request->query('after', '0'); $before = (int) $request->query('before', '0'); $messages = StaffChat::messages($found, max(0, $after), max(0, $before)); if ($after === 0 && $before === 0) { StaffChat::markRead($found, $user); } $first = $messages->first(); return new JsonResponse([ 'messages' => StaffPresenter::messages($messages, $user, $found), 'canPost' => StaffChat::canWrite($found, $user), 'more' => $after === 0 && $first !== null && StaffChat::hasOlder($found, (int) $first->id), ]); } public function send(ClientApiRequest $request, string $uuid): JsonResponse { $user = $this->actor($request); $data = $request->validate(['body' => ['required', 'string', 'min:1', 'max:2000']]); $found = $this->visible($user, $uuid); $message = StaffChat::post($found, $user, (string) $data['body']); return new JsonResponse(['message' => StaffPresenter::message($message, $user, $found)]); } private function actor(ClientApiRequest $request): User { $user = $request->user(); if (!Staff::canAct($user)) { throw new NotFoundHttpException(); } return $user; } private function visible(User $user, string $uuid): StaffRequest { $query = StaffRequest::query()->where('uuid', $uuid); if ($user->root_admin !== true) { $query->where(function (Builder $builder) use ($user) { $builder->where('staff_id', $user->id) ->orWhere(function (Builder $waiting) use ($user) { $waiting->where('status', StaffRequest::PENDING) ->where('direction', StaffRequest::DIRECTION_OWNER) ->where(function (Builder $addressed) use ($user) { $addressed->whereNull('target_staff_id')->orWhere('target_staff_id', $user->id); }); }); }); } $found = $query->first(); if ($found === null) { throw new NotFoundHttpException(); } return $found; } private function single(StaffRequest $request, User $viewer): JsonResponse { return new JsonResponse(['request' => StaffPresenter::request($request->refresh(), $viewer, true)]); } } 